import{_ as e,o as r,c as d,X as a}from"./chunks/framework.pSp8ynCZ.js";const f=JSON.parse('{"title":"Timing and observations: prof","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-prof.md","filePath":"reference-prof.md"}'),o={name:"rust/api/reference-prof.md"};function s(i,t,c,n,l,p){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="timing-and-observations-prof" tabindex="-1">Timing and observations: prof <a class="header-anchor" href="#timing-and-observations-prof" aria-label="Permalink to &quot;Timing and observations: prof&quot;">​</a></h1><p><code>cellpack::prof</code> defines timing sites, masks, per-thread records and aggregated reports. Ordinary loader users select a <code>SiteMask</code> and read <code>RunStats.profile</code>. Applications instrumenting native work can use the lower-level profiler types.</p><h2 id="application-facing-interfaces" tabindex="-1">Application-facing interfaces <a class="header-anchor" href="#application-facing-interfaces" aria-label="Permalink to &quot;Application-facing interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Inputs</th><th>Returns / meaning</th></tr></thead><tbody><tr><td><code>SiteMask::parse</code></td><td>Site/group names</td><td>Checked mask; unknown names return a loader configuration error</td></tr><tr><td><code>SiteMask::NONE / ALL</code></td><td>None</td><td>No sites / every declared site</td></tr><tr><td><code>contains / names</code></td><td>Site or mask</td><td>Membership / enabled site names</td></tr><tr><td><code>SITES / GROUPS</code></td><td>Static declarations</td><td>Descriptions and named groups</td></tr><tr><td><code>ProfileReport::site</code></td><td>Name</td><td>Optional recorded <code>SiteReport</code></td></tr><tr><td><code>ProfileReport::time</code></td><td>Name</td><td>Total duration, zero if not recorded</td></tr></tbody></table><p><code>SiteInfo</code> records a name, <code>Kind</code>, <code>Detail</code>, optional parent, and description. <code>Kind</code> selects spans or histograms. <code>Detail</code> selects a total, per-schema records, or schema/size-band/partial-row records.</p><p><code>ProfileReport</code> has schema count, band count and ordered site reports. <code>SiteReport</code> includes calls, inclusive <code>time</code>, <code>self_time</code>, per-key details and optional histogram entries. Histogram lower bounds are nanoseconds. <code>DetailReport</code> identifies a schema or schema/band/partial key, calls and duration.</p><p>Missing timing data is not proof that a phase took no time. Check the selected mask. Inclusive parent and child durations overlap; do not sum every site as an end-to-end elapsed time. <a href="/cellpack-docs/rust/docs/profiling.html">Profiling</a> explains the event/timing split.</p><h2 id="instrumentation-interfaces" tabindex="-1">Instrumentation interfaces <a class="header-anchor" href="#instrumentation-interfaces" aria-label="Permalink to &quot;Instrumentation interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility and contract</th></tr></thead><tbody><tr><td><code>Clock</code></td><td>Clock readings and nanoseconds-per-tick conversion</td></tr><tr><td><code>Layout::new(schemas, bands)</code></td><td>Detail/histogram word layout; zero dimensions are clamped to one</td></tr><tr><td><code>Layout::words</code></td><td>Required record length in <code>u64</code> words</td></tr><tr><td><code>Record::new</code></td><td>Zeroed words for the layout</td></tr><tr><td><code>Record::add</code></td><td>Adds another record, growing the destination if necessary</td></tr><tr><td><code>Profiler</code></td><td>Start/stop, keyed detail, tick/mark accounting, per-thread fork and report setup</td></tr><tr><td><code>Off</code></td><td>Untimed implementation, no clock-read work</td></tr><tr><td><code>On</code></td><td>Timed implementation holding one thread&#39;s mutable record</td></tr><tr><td><code>Setup</code></td><td>Creates a compatible profiler and converts records to reports</td></tr><tr><td><code>Snapshots</code></td><td>Per-thread publication slots and an aggregated live sum</td></tr></tbody></table><p>Keep layout, site and detail keys compatible. A thread owns its own mutable record; fork profilers for other threads rather than concurrently writing one. Raw clock ticks are not nanoseconds until converted.</p><p><code>Snapshots::new(threads, words)</code> allocates publication slots. <code>publish(i, words)</code> is for the single owning writer of slot <code>i</code>. <code>sum()</code> returns a consistent per-slot sum, retrying in-progress publications. It is a live observation, not an atomic barrier across all threads.</p><h2 id="complete-interface-index" tabindex="-1">Complete interface index <a class="header-anchor" href="#complete-interface-index" aria-label="Permalink to &quot;Complete interface index&quot;">​</a></h2><h3 id="structs" tabindex="-1">Structs <a class="header-anchor" href="#structs" aria-label="Permalink to &quot;Structs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-Clock.html"><code>Clock</code></a></td><td>Run-time clock for profiled runs: the TSC where it is invariant, else nanoseconds since the run started. Readings are converted to time once, when the run reports.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-DetailReport.html"><code>DetailReport</code></a></td><td>One detail slot of a site.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-Layout.html"><code>Layout</code></a></td><td>Where each site’s records lie in a Record : the offset of its detail slots and of its histogram, and the record’s total length.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-Off.html"><code>Off</code></a></td><td>No profiling.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-On.html"><code>On</code></a></td><td>Profiling of the sites in a mask.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-ProfileReport.html"><code>ProfileReport</code></a></td><td>What a profiled run recorded, per enabled site.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-Record.html"><code>Record</code></a></td><td>One thread’s site records, as plain words.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-Setup.html"><code>Setup</code></a></td><td>A run’s profiling setup: the mask, the clock and the record layout.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-SiteInfo.html"><code>SiteInfo</code></a></td><td>A site’s static description.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-SiteMask.html"><code>SiteMask</code></a></td><td>A set of sites, one bit per site in Site order.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-SiteReport.html"><code>SiteReport</code></a></td><td>One site’s totals, as a report shows them.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-struct-Snapshots.html"><code>Snapshots</code></a></td><td>Snapshot slots: one per thread, each a seqlock over plain words, so a reader never blocks a writer.</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-prof-enum-Detail.html"><code>Detail</code></a></td><td>The detail a site keeps per call.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-enum-Kind.html"><code>Kind</code></a></td><td>Kinds of site records.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-enum-Site.html"><code>Site</code></a></td><td>A timing point.</td></tr></tbody></table><h3 id="constants" tabindex="-1">Constants <a class="header-anchor" href="#constants" aria-label="Permalink to &quot;Constants&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-prof-constant-BUCKETS.html"><code>BUCKETS</code></a></td><td>Log2 buckets of a histogram site.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-constant-GROUPS.html"><code>GROUPS</code></a></td><td>Named site sets; SiteMask::parse accepts any of these names beside the site names and all .</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-constant-MAX_SITES.html"><code>MAX_SITES</code></a></td><td>Most sites a mask holds.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-prof-constant-SITES.html"><code>SITES</code></a></td><td>Every site, in Site order.</td></tr></tbody></table><h3 id="traits" tabindex="-1">Traits <a class="header-anchor" href="#traits" aria-label="Permalink to &quot;Traits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-prof-trait-Profiler.html"><code>Profiler</code></a></td><td>Timing hooks; see the module documentation.</td></tr></tbody></table>',20)])])}const u=e(o,[["render",s]]);export{f as __pageData,u as default};
